//! Compare real files against independently annotated beat timestamps.
//! Manifest: [{"path":"...","bpm":120,"beats":[0.2,0.7,...],"annotation_source":"..."}]
use anyhow::{ensure,Result};use serde::Deserialize;
#[derive(Deserialize)]struct Recording{path:String,bpm:f32,beats:Vec<f32>,annotation_source:String}
fn main()->Result<()>{let path=std::env::args().nth(1).ok_or_else(||anyhow::anyhow!("Pass independent annotation manifest"))?;let inputs:Vec<Recording>=serde_json::from_slice(&std::fs::read(path)?)?;ensure!(!inputs.is_empty(),"No annotated recordings");let mut reports=Vec::new();for input in inputs{ensure!(input.bpm.is_finite()&&input.bpm>0.&&input.beats.len()>=2&&!input.annotation_source.trim().is_empty()&&input.beats.windows(2).all(|p|p[1]>p[0])&&input.beats.iter().all(|v|v.is_finite()&&*v>=0.),"Invalid independent annotation");let started=std::time::Instant::now();let candidate=std::env::args().any(|v|v=="--candidate");let f=if candidate{musicos_tauri::structure::scan_multiband(std::path::Path::new(&input.path),None,0.,||true)?}else{musicos_tauri::structure::scan(std::path::Path::new(&input.path),None,0.,||true)?};let mut used=vec![false;input.beats.len()];let mut correct=0;for beat in &f.beats{if let Some((i,distance))=input.beats.iter().enumerate().filter(|(i,_)|!used[*i]).map(|(i,v)|(i,(v-beat).abs())).min_by(|a,b|a.1.total_cmp(&b.1)){if distance<=0.07{used[i]=true;correct+=1;}}}let precision=correct as f32/f.beats.len().max(1)as f32;let recall=correct as f32/input.beats.len()as f32;let score=if precision+recall>0.{2.*precision*recall/(precision+recall)}else{0.};reports.push(serde_json::json!({"path":input.path,"annotation_source":input.annotation_source,"reference_bpm":input.bpm,"estimated_bpm":f.tempo,"beat_f1_70ms":score,"beat_confidence":f.beat_confidence,"safe_fallback":f.beat_confidence<0.5||f.phrases.is_empty(),"milliseconds":started.elapsed().as_millis()}));}println!("{}",serde_json::to_string_pretty(&reports)?);Ok(())}
